package com.ne.business.dflq.can.controller;

import com.ne.boot.common.entity.Page;
import com.ne.boot.common.entity.Response;
import com.ne.business.dflq.can.entity.CanRecordTask;
import com.ne.business.dflq.can.entity.dto.CopyTaskDTO;
import com.ne.business.dflq.can.entity.dto.CreateTaskDTO;
import com.ne.business.dflq.can.entity.dto.UpdateClearTimeDTO;
import com.ne.business.dflq.can.entity.dto.UpdateStatusDTO;
import com.ne.business.dflq.can.entity.query.CanRecordTaskQuery;
import com.ne.business.dflq.can.entity.vo.DictItem;
import com.ne.business.dflq.can.enums.CommandEnum;
import com.ne.business.dflq.can.enums.CommandResultEnum;
import com.ne.business.dflq.can.enums.ConvertStatusEnum;
import com.ne.business.dflq.can.enums.TaskStatusEnum;
import com.ne.business.dflq.can.entity.vo.CanMsgVo;
import com.ne.business.dflq.can.entity.vo.CanRecordTaskVo;
import com.ne.business.dflq.can.service.CanRecordTaskService;
import com.ne.business.dflq.can.utils.PageResult;
import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.BeanUtils;
import org.springframework.web.bind.annotation.*;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * CAN数据任务控制层
 *
 * @author weihong
 * @date  2026-2-26
 */
@Api(tags = "事后录制任务相关")
@RestController
@RequestMapping("/canRecordTask")
@RequiredArgsConstructor
public class CanRecordTaskController {
    private final CanRecordTaskService canTaskService;

    @ApiOperation("查询CAN数据录制任务")
    @GetMapping("/list")
    public Response query(CanRecordTaskQuery query, Page page) {
        boolean fetchAll = query.getFetchAll() != null && query.getFetchAll();
        if (fetchAll) {
            page.setPageSize((long) 1000);
        }
        List<CanRecordTask> canTaskList = canTaskService.query(query, page);
        int count = canTaskService.getCount(query);
        page.setPageIndex(page.getPageIndex());
        page.setPageSize(fetchAll ? (long) count : page.getPageSize());
        page.setTotalCount((long) count);
        return Response.success(canTaskList,page);
    }

    @ApiOperation("详情")
    @GetMapping("/detail")
    public Response detail(Long id) {
        CanRecordTask canTask = canTaskService.getById(id);
        if (canTask == null) {
            return Response.success(null);
        }
        CanRecordTaskVo vo = convertToVo(canTask);
        return Response.success(vo);
    }

    /**
     * 实体转VO
     * @param canTask 实体对象
     * @return VO对象
     */
    private CanRecordTaskVo convertToVo(CanRecordTask canTask) {
        CanRecordTaskVo vo = new CanRecordTaskVo();
        BeanUtils.copyProperties(canTask, vo);
        // 处理CAN报文数组
        String canMessage = canTask.getCanMessage();
        vo.setCanMessageList(
                canMessage != null ? Arrays.asList(canMessage.split(",")) : null
        );
        return vo;
    }

    @ApiOperation("修改清除时间")
    @PutMapping("/updateClearTime")
    public Response updateClearTime(@RequestBody UpdateClearTimeDTO dto) {
        canTaskService.updateClearTime(dto);
        return Response.success();
    }

    @ApiOperation("删除")
    @DeleteMapping("/delete")
    public Response delete(Long id) {
        return canTaskService.delete(id);
    }

    @ApiOperation("刷新CAN数据录制任务")
    @GetMapping("/refresh")
    public Response refresh(CanRecordTaskQuery query, Page page) {
        boolean fetchAll = query.getFetchAll() != null && query.getFetchAll();
        if (fetchAll) {
            page.setPageSize((long) 1000);
        }
        List<CanRecordTask> canTaskList = canTaskService.query(query, page);
        if (fetchAll) {
            page.setPageSize(page.getTotalCount());
        }
        PageResult<CanRecordTask> pageResult = PageResult.from(page, canTaskList);
        if (fetchAll) {
            pageResult.setFetchAll(true);
        }
        return Response.success(pageResult);
    }

    @ApiOperation("创建CAN数据录制任务")
    @PostMapping("/create")
    public Response create(@RequestBody CreateTaskDTO dto) {
        canTaskService.create(dto);
        return Response.success();
    }

    @ApiOperation("复制")
    @PostMapping("/copy")
    public Response copy(@RequestBody CopyTaskDTO dto) {
        canTaskService.copy(dto);
        return Response.success();
    }

    @ApiOperation("更新状态")
    @PutMapping("/updateStatus")
    public Response updateStatus(@RequestBody UpdateStatusDTO dto) {
        return canTaskService.updateStatus(dto);
    }

    @ApiOperation("查询CAN报文")
    @GetMapping("/queryCanMsg")
    public Response queryCanMsg(CanRecordTaskQuery query, Page page) {
        boolean fetchAll = query.getFetchAll() != null && query.getFetchAll();
        if (fetchAll) {
            page.setPageSize((long) 1000);
        }
        List<CanMsgVo> canTaskList = canTaskService.queryCanMsg(query, page);
        if (fetchAll) {
            page.setPageSize(page.getTotalCount());
        }
        PageResult<CanMsgVo> pageResult = PageResult.from(page, canTaskList);
        if (fetchAll) {
            pageResult.setFetchAll(true);
        }
        return Response.success(pageResult);
    }

    @ApiOperation("根据清除时间删除任务")
    @DeleteMapping("/deleteByClearTime")
    public Response deleteByClearTime() {
        canTaskService.deleteByClearTime();
        return Response.success();
    }

    @ApiOperation("查询可用VIN（暂定）")
    @GetMapping("/queryAvailableVin")
    public Response queryAvailableVin() {
        return Response.success(canTaskService.queryAvailableVin());
    }

    @ApiOperation("根据VIN查询矩阵平台")
    @GetMapping("/queryMatrixPlatform")
    public Response queryMatrixPlatform(String vin) {
        return Response.success(canTaskService.queryMatrixPlatform(vin));
    }

    @ApiOperation("查询字典")
    @GetMapping("/dict")
    public Response getDict() {
        Map<String, List<DictItem>> dict = new HashMap<>();
        dict.put("convertStatus", ConvertStatusEnum.toDictList());
        dict.put("taskStatus", TaskStatusEnum.toDictList());
        dict.put("command", CommandEnum.toDictList());
        dict.put("commandResult", CommandResultEnum.toDictList());
        return Response.success(dict);
    }
}

