    public static BaseResult success() {
        BaseResult baseResult = new BaseResult();
        baseResult.resultCode = 0;
        return baseResult;
    }

    public static BaseResult success(TboxResponseResult data) {
        BaseResult baseResult = success();
        baseResult.data = new BaseResultData();
        baseResult.data.setTboxResponseResult(data);
        return baseResult;
    }

    public static BaseResult success(boolean sentWakeUpSms, long sentWakeUpSmsTime, TboxResponseResult data) {
        BaseResult baseResult = success(data);
        baseResult.data.setSentWakeUpSms(sentWakeUpSms);
        baseResult.data.setSentWakeUpSmsTime(sentWakeUpSmsTime);
        return baseResult;
    }
