        baseResult.data.setSentWakeUpSmsTime(sentWakeUpSmsTime);
        baseResult.data.setTspReqId(tspReqId);
        return baseResult;
    }

    public static BaseResult error() {
        BaseResult baseResult = new BaseResult();
        baseResult.resultCode = -1;
        return baseResult;
    }

    public static BaseResult error(IError error) {
        BaseResult baseResult = error();
        baseResult.message = error.getErrorMessage();
        baseResult.messageCode = error.getErrorCode();
        return baseResult;
    }

    public static BaseResult error(String message, String messageCode) {
        BaseResult baseResult = error();
        baseResult.message = message;
        baseResult.messageCode = messageCode;
        return baseResult;
    }

    public static BaseResult error(String message, String messageCode, SendCommandResultData data) {
        BaseResult baseResult = error();
        baseResult.message = message;
        baseResult.messageCode = messageCode;

        if (data != null) {
            baseResult.data = new BaseResultData();
            baseResult.data.setSentWakeUpSms(data.isSentWakeUpSms());
            baseResult.data.setSentWakeUpSmsTime(data.getSentWakeUpSmsTime());
            baseResult.data.setTboxResponseResult(null);
