package com.ne.business.dflq.can.entity;

import lombok.Getter;
import lombok.Setter;


/**
 * @author liping
 * @version 1.0
 * @date 2020/9/25 10:20
 */
@Getter
@Setter
public class TboxResponseResult {
    String remoteControlAck;
    String result;
    String errorCode;
    Object data;

    public static TboxResponseResult success(Object data) {
        TboxResponseResult responseResult = new TboxResponseResult();
        responseResult.setResult("1");
        responseResult.errorCode = "0";
        if (data != null) {
            responseResult.data = data;
        }
        return responseResult;
    }

    public static TboxResponseResult fail(String errorCode) {
        TboxResponseResult responseResult = new TboxResponseResult();
        responseResult.setResult("0");
        responseResult.errorCode = errorCode;
        return responseResult;
    }

    public static TboxResponseResult fail(String errorCode, Object data) {
        TboxResponseResult responseResult = new TboxResponseResult();
        responseResult.setResult("0");
        if (data != null) {
            responseResult.data = data;
        }
        responseResult.errorCode = errorCode;
        return responseResult;
    }
}

