package com.ne.business.dflq.can.enums;

import com.ne.business.dflq.can.entity.vo.DictItem;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 任务状态枚举
 *
 * @author weihong
 */
public enum TaskStatusEnum {

    NOT_STARTED(0, "未启动"),
    STARTING(1, "启动中"),
    RUNNING(2, "执行中"),
    STOPPING(3, "停止中"),
    ENDED(4, "已结束");

    private final int code;
    private final String label;

    TaskStatusEnum(int code, String label) {
        this.code = code;
        this.label = label;
    }

    public int getCode() {
        return code;
    }

    public String getLabel() {
        return label;
    }

    /**
     * 根据编码查找枚举
     */
    public static TaskStatusEnum fromCode(int code) {
        for (TaskStatusEnum e : values()) {
            if (e.code == code) {
                return e;
            }
        }
        return null;
    }

    /**
     * 转换为字典列表（供前端下拉使用）
     */
    public static List<DictItem> toDictList() {
        return Arrays.stream(values())
                .map(e -> new DictItem(e.code, e.label))
                .collect(Collectors.toList());
    }
}

