package com.ne.business.dflq.can.kafka;

import com.alibaba.fastjson.JSON;
import com.ne.boot.common.util.JsonUtil;
import com.ne.business.dflq.can.entity.CanRecordTask;
import com.ne.business.dflq.can.entity.dto.AddFileDTO;
import com.ne.business.dflq.can.enums.ConvertStatusEnum;
import com.ne.business.dflq.can.enums.TaskStatusEnum;
import com.ne.business.dflq.can.service.CanRecordFileService;
import com.ne.business.dflq.can.service.CanRecordTaskService;
import com.ne.dflq.bp.vo.PredictiveDataVo;
import com.ne.ice.tbox.protocol.TboxTspProtocolDecoder;
import com.ne.ice.tbox.protocol.dto.DecodeMixC8Result;
import com.ne.ice.tbox.protocol.dto.TboxMessagePlus;
import com.ne.ice.tbox.protocol.enums.VapGatewayType;
import com.ne.ice.tbox.protocol.utils.ByteUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.lang3.StringUtils;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;

import java.net.URI;
import java.util.Date;
import java.util.List;


@Slf4j
@RequiredArgsConstructor
@Component
public class CanRecordingListener {

    private final CanRecordFileService canRecordFileService;

    private final CanRecordTaskService canRecordTaskService;

    /** C8 上报的任务状态：运行中 */
    private static final int C8_TASK_STATUS_RUNNING = 1;
    /** C8 上报的任务状态：已结束 */
    private static final int C8_TASK_STATUS_ENDED = 2;

    @KafkaListener(id = "${spring.kafka.properties.RecordAfterwardsTopic:record_afterwards}", topics = {"${spring.kafka.properties.RecordAfterwardsTopic:record_afterwards}"}, idIsGroup = false, groupId = "${spring.kafka.consumer.group.id:triggered_event}", containerFactory = "kafkaListenerContainerFactory")
    protected void listen(final List<String> list) {
        log.info("CanRecordingListener, datas: {}", JsonUtil.writeValueAsString(list));

        if (CollectionUtils.isNotEmpty(list)) {
            for (String s : list) {
                try {
                    if (StringUtils.isBlank(s)) {
                        continue;
                    }
                    PredictiveDataVo predictiveDataVo = JSON.parseObject(s, PredictiveDataVo.class);
                    if (predictiveDataVo == null) {
                        log.warn("topic triggered_event - message parse result is null, data:{}", s);
                        continue;
                    }
                    if (StringUtils.isBlank(predictiveDataVo.getHex())) {
                        log.warn("topic record_afterwards - hex is blank, data:{}", s);
                        continue;
                    }

                    Long gatewayReceiveTime = predictiveDataVo.getGatewayReceiveTime() == null ? 0L : predictiveDataVo.getGatewayReceiveTime();
                    TboxMessagePlus tboxMessagePlus = TboxTspProtocolDecoder.decodeHeader(ByteUtils.hexStringToByteArray(predictiveDataVo.getHex()), VapGatewayType.MIX_GATEWAY, gatewayReceiveTime);
                    DecodeMixC8Result decodeMixC8Result = TboxTspProtocolDecoder.decodeMixDataC8(tboxMessagePlus);
                    if (decodeMixC8Result == null) {
                        log.warn("topic record_afterwards - C8 decode result is null, data:{}", s);
                        continue;
                    }
                    Long recordTaskId = decodeMixC8Result.getRecordTaskId();
                    Long recordFileId = getRecordFileId(decodeMixC8Result.getRecordFileId(), predictiveDataVo.getEventId());
                    Long recordFileStartTimestamp = decodeMixC8Result.getRecordFileStartTimestamp();
                    Long recordFileEndTimestamp = decodeMixC8Result.getRecordFileEndTimestamp();
                    Integer recordTaskStatus = decodeMixC8Result.getRecordTaskStatus();

                    if (recordTaskId == null || recordFileStartTimestamp == null || recordFileEndTimestamp == null) {
                        log.warn("topic record_afterwards - required C8 field is null, data:{}", s);
                        continue;
                    }

                    // 转换时间戳为 yyyy-MM-dd HH:mm:ss 格式
                    Date recordFileStartTime = new Date(recordFileStartTimestamp);
                    Date recordFileEndTime = new Date(recordFileEndTimestamp);
                    AddFileDTO addFileDTO = new AddFileDTO();
                    addFileDTO.setId(recordFileId);
                    addFileDTO.setFileName(resolveFileName(predictiveDataVo.getUrl()));
                    addFileDTO.setTaskId(recordTaskId);
                    addFileDTO.setStartTime(recordFileStartTime);
                    addFileDTO.setEndTime(recordFileEndTime);
                    addFileDTO.setConvertStatus(ConvertStatusEnum.NOT_CONVERTED.getCode());
                    canRecordFileService.add(addFileDTO);

                    syncTaskStatus(recordTaskId, recordTaskStatus);
                } catch (Exception e) {
                    log.error("topic triggered_event - handler error data:{}", s, e);
                }
            }
        }
    }

    private Long getRecordFileId(Long reportedRecordFileId, Integer assignedRecordFileId) {
        if (reportedRecordFileId != null && reportedRecordFileId > 0) {
            return reportedRecordFileId;
        }
        return assignedRecordFileId == null ? null : assignedRecordFileId.longValue();
    }

    private String resolveFileName(String url) {
        if (StringUtils.isBlank(url)) {
            return null;
        }
        try {
            String path = URI.create(url).getPath();
            if (StringUtils.isNotBlank(path)) {
                int index = path.lastIndexOf('/');
                return index >= 0 ? path.substring(index + 1) : path;
            }
        } catch (Exception e) {
            log.warn("resolve record file name failed, url: {}", url, e);
        }
        String path = url;
        int queryIndex = path.indexOf('?');
        if (queryIndex >= 0) {
            path = path.substring(0, queryIndex);
        }
        int slashIndex = path.lastIndexOf('/');
        return slashIndex >= 0 ? path.substring(slashIndex + 1) : path;
    }

    private void syncTaskStatus(Long taskId, Integer recordTaskStatus) {
        if (taskId == null || recordTaskStatus == null) {
            return;
        }

        CanRecordTask task = canRecordTaskService.getById(taskId);
        if (task == null) {
            log.warn("record task not found when syncing C8 status, taskId: {}", taskId);
            return;
        }

        Integer currentStatus = task.getStatus();
        Integer nextStatus = null;
        if (recordTaskStatus == C8_TASK_STATUS_RUNNING
                && (Integer.valueOf(TaskStatusEnum.NOT_STARTED.getCode()).equals(currentStatus)
                || Integer.valueOf(TaskStatusEnum.STARTING.getCode()).equals(currentStatus))) {
            nextStatus = TaskStatusEnum.RUNNING.getCode();
        } else if (recordTaskStatus == C8_TASK_STATUS_ENDED
                && (Integer.valueOf(TaskStatusEnum.RUNNING.getCode()).equals(currentStatus)
                || Integer.valueOf(TaskStatusEnum.STOPPING.getCode()).equals(currentStatus))) {
            nextStatus = TaskStatusEnum.ENDED.getCode();
        }

        if (nextStatus == null) {
            return;
        }

        CanRecordTask updateTask = new CanRecordTask();
        updateTask.setId(taskId);
        updateTask.setStatus(nextStatus);
        canRecordTaskService.updateStatusDirect(updateTask);
    }
}

