package com.ne.business.dflq.can.kafka;

import com.alibaba.fastjson.JSON;
import com.ne.business.dflq.can.entity.CanRecordTask;
import com.ne.business.dflq.can.entity.dto.CanRecordTaskMessage;
import com.ne.business.dflq.can.enums.CommandEnum;
import com.ne.business.dflq.can.enums.CommandResultEnum;
import com.ne.business.dflq.can.enums.TaskStatusEnum;
import com.ne.business.dflq.can.service.CanRecordTaskService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.lang3.StringUtils;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * CAN录制任务状态监听器
 * 监听Kafka消息，根据任务ID更新CAN_RECORDING_TASK表的状态
 *
 * @author weihong
 * @date 2026-06-02
 */
@Slf4j
@RequiredArgsConstructor
@Component
public class CanRecordTaskListener {

    private final CanRecordTaskService canRecordTaskService;

    // TODO: 确认Kafka主题配置
    private static final String TOPIC = "${spring.kafka.properties.CanRecordTaskTopic:can_record_task_status}";
    private static final String GROUP_ID = "${spring.kafka.consumer.group.id:can_record_task_group}";

    /**
     * 监听录制任务状态变更消息
     * 批量消费Kafka消息，解析后更新对应任务的状态
     *
     * @param list 消息列表
     */
    @KafkaListener(
            id = TOPIC,
            topics = {TOPIC},
            idIsGroup = false,
            groupId = GROUP_ID,
            containerFactory = "kafkaListenerContainerFactory"
    )
    protected void listen(final List<String> list) {
        if (CollectionUtils.isEmpty(list)) {
            return;
        }

        for (String message : list) {
            try {
                if (StringUtils.isBlank(message)) {
                    continue;
                }
                processMessage(message);
            } catch (Exception e) {
                log.error("CAN录制任务状态监听处理异常, message: {}", message, e);
            }
        }
    }

    /**
     * 处理单条消息
     * 解析消息内容并更新任务状态
     *
     * @param message JSON格式的消息内容
     */
    private void processMessage(String message) {
        // 解析消息
        CanRecordTaskMessage taskMessage = JSON.parseObject(message, CanRecordTaskMessage.class);
        if (taskMessage == null) {
            log.warn("消息解析结果为空, message: {}", message);
            return;
        }

        Long taskId = taskMessage.getTaskId();
        Integer status = taskMessage.getStatus();
        Integer commandId = taskMessage.getCommandId();

        // 参数校验
        if (taskId == null) {
            log.warn("任务ID为空, message: {}", message);
            return;
        }
        if (status == null) {
            log.warn("任务状态为空, taskId: {}, message: {}", taskId, message);
            return;
        }
        if (commandId == null) {
            log.warn("命令ID为空, taskId: {}, message: {}", commandId, message);
            return;
        }

        // 查询任务是否存在
        CanRecordTask task = canRecordTaskService.getById(taskId);
        if (task == null) {
            log.warn("任务不存在, taskId: {}", taskId);
            return;
        }

        // 直接更新任务状态（不发送下行指令）
        CanRecordTask updateTask = new CanRecordTask();
        updateTask.setId(taskId);

        Integer newStatus = null;
        if (commandId == CommandEnum.START.getCode()) {
            // 启动指令：成功→执行中，失败→未启动
            newStatus = (status == CommandResultEnum.SUCCESS.getCode())
                    ? TaskStatusEnum.RUNNING.getCode()
                    : TaskStatusEnum.NOT_STARTED.getCode();
        } else if (commandId == CommandEnum.STOP.getCode()) {
            // 停止指令：成功→已结束，失败→执行中
            newStatus = (status == CommandResultEnum.SUCCESS.getCode())
                    ? TaskStatusEnum.ENDED.getCode()
                    : TaskStatusEnum.RUNNING.getCode();
        }
        updateTask.setStatus(newStatus);
        canRecordTaskService.updateStatusDirect(updateTask);

        log.info("任务状态更新成功, taskId: {}, oldStatus: {}, newStatus: {}",
                taskId, task.getStatus(), status);
    }
}

