package com.ne.business.dflq.can.scheduled;

import com.ne.business.dflq.can.service.CanRecordTaskService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;

/**
 * CAN录制任务定时清理
 *
 * @author claude
 * @date 2026-07-14
 */
@Configuration
@EnableScheduling
@Slf4j
@RequiredArgsConstructor
public class CanRecordTaskClearScheduled {

    private final CanRecordTaskService canRecordTaskService;

    /**
     * 每天凌晨1点执行，清理过期的录制任务及关联文件
     */
    @Scheduled(cron = "0 0 1 * * ?")
    public void clearExpiredTasks() {
        log.info("开始清理过期的CAN录制任务");
        try {
            canRecordTaskService.deleteByClearTime();
            log.info("过期CAN录制任务清理完成");
        } catch (Exception e) {
            log.error("清理过期CAN录制任务失败", e);
        }
    }
}

