1	package com.ne.business.dflq.can.service;
2	
3	import com.ne.business.dflq.can.config.CosConfig;
4	import com.ne.business.dflq.can.entity.vo.CanRecordFileVo;
5	import com.ne.business.dflq.can.enums.ConvertStatusEnum;
6	import com.ne.business.dflq.can.utils.CosFileDownloader;
7	import lombok.RequiredArgsConstructor;
8	import lombok.extern.slf4j.Slf4j;
9	import org.apache.poi.common.usermodel.HyperlinkType;
10	import org.apache.poi.ss.usermodel.*;
11	import org.apache.poi.xssf.usermodel.XSSFWorkbook;
12	import org.springframework.stereotype.Service;
13	import org.springframework.util.CollectionUtils;
14	
15	import javax.servlet.http.HttpServletResponse;
16	import java.io.ByteArrayOutputStream;
17	import java.io.IOException;
18	import java.net.URLEncoder;
19	import java.text.SimpleDateFormat;
20	import java.util.List;
21	import java.util.zip.ZipEntry;
22	import java.util.zip.ZipOutputStream;
23	
24	/**
25	 * 专用导出Excel文件服务层
26	 *
27	 * @author weihong
28	 */
29	@Slf4j
30	@Service
31	@RequiredArgsConstructor
32	public class ExcelExportService {
33	
34	    private final CosConfig cosConfig;
35	
36	    /**
37	     * 导出Excel + ASC文件压缩包
38	     * 单个文件和多个文件统一走此方法，生成zip压缩包返回
39	     * zip内包含：一个Excel文件（所有记录在一个sheet中）+ 对应的ASC文件
40	     *
41	     * @param dataList 数据列表
42	     * @param fileName 压缩包文件名（不含扩展名）
43	     * @param response HTTP响应
44	     */
45	    public void exportExcelWithAscFiles(List<CanRecordFileVo> dataList, String fileName,
46	                                         HttpServletResponse response) throws IOException {
47	        if (CollectionUtils.isEmpty(dataList)) {
48	            throw new IllegalArgumentException("数据列表不能为空");
49	        }
50	
51	        // 先在内存中构建完整zip，确保无异常后再写入response
52	        ByteArrayOutputStream baos = new ByteArrayOutputStream();
53	        try (ZipOutputStream zipOut = new ZipOutputStream(baos)) {
54	            // 生成Excel并写入zip
55	            Workbook workbook = createExcelWorkbook(dataList);
56	            ZipEntry excelEntry = new ZipEntry(fileName + ".xlsx");
57	            zipOut.putNextEntry(excelEntry);
58	            workbook.write(zipOut);
59	            workbook.close();
60	            zipOut.closeEntry();
61	
62	            // 下载ASC文件并写入zip
63	            for (CanRecordFileVo data : dataList) {
64	                if (data.getConvertStatus() != null && data.getConvertStatus() == ConvertStatusEnum.CONVERTED.getCode()
65	                        && data.getConvertFileName() != null && !data.getConvertFileName().isEmpty()) {
66	                    try {
67	                        String cosKey = cosConfig.getConvertedDir() + data.getConvertFileName();
68	                        log.info("下载ASC文件: bucket={}, key={}", cosConfig.getBucketName(), cosKey);
69	                        byte[] ascData = CosFileDownloader.downloadFromCos(cosConfig.getBucketName(), cosKey);
70	
71	                        ZipEntry ascEntry = new ZipEntry(data.getConvertFileName());
72	                        zipOut.putNextEntry(ascEntry);
73	                        zipOut.write(ascData);
74	                        zipOut.closeEntry();
75	                        log.info("ASC文件写入zip成功: {}", data.getConvertFileName());
76	                    } catch (Exception e) {
77	                        log.error("下载ASC文件失败，跳过: convertFileName={}, 错误: {}",
78	                                data.getConvertFileName(), e.getMessage(), e);
79	                    }
80	                }
81	            }
82	        }
83	
84	        // zip构建完成，无异常，设置响应头并以流写入response
85	        byte[] zipBytes = baos.toByteArray();
86	        response.setContentType("application/zip");
87	        response.setHeader("Content-Disposition",
88	                "attachment;filename=" + URLEncoder.encode(fileName + ".zip", "UTF-8"));
89	        response.setContentLength(zipBytes.length);
90	        response.getOutputStream().write(zipBytes);
91	        response.getOutputStream().flush();
92	    }
93	
94	    /**
95	     * 创建Excel工作簿
96	     * 表头：任务名称 | 录制文件名 | 开始时间 | 结束时间
97	     */
98	    private Workbook createExcelWorkbook(List<CanRecordFileVo> dataList) {
99	        Workbook workbook = new XSSFWorkbook();
100	        CreationHelper creationHelper = workbook.getCreationHelper();
101	        Sheet sheet = workbook.createSheet("录制文件列表");
102	
103	        // 表头列定义
104	        String[] headers = {"任务名称", "录制文件名", "开始时间", "结束时间"};
105	
106	        // 表头样式
107	        CellStyle headerStyle = workbook.createCellStyle();
108	        Font headerFont = workbook.createFont();
109	        headerFont.setBold(true);
110	        headerStyle.setFont(headerFont);
111	
112	        // 超链接样式（蓝色下划线）
113	        CellStyle linkStyle = workbook.createCellStyle();
114	        Font linkFont = workbook.createFont();
115	        linkFont.setUnderline(Font.U_SINGLE);
116	        linkFont.setColor(IndexedColors.BLUE.getIndex());
117	        linkStyle.setFont(linkFont);
118	
119	        // 创建表头行
120	        Row headerRow = sheet.createRow(0);
121	        for (int i = 0; i < headers.length; i++) {
122	            Cell cell = headerRow.createCell(i);
123	            cell.setCellValue(headers[i]);
124	            cell.setCellStyle(headerStyle);
125	        }
126	
127	        // 日期格式
128	        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
129	
130	        // 创建数据行
131	        for (int i = 0; i < dataList.size(); i++) {
132	            CanRecordFileVo data = dataList.get(i);
133	            Row dataRow = sheet.createRow(i + 1);
134	
135	            // 任务名称
136	            dataRow.createCell(0).setCellValue(data.getTaskName() != null ? data.getTaskName() : "");
137	
138	            // 录制文件名（已转换的文件添加超链接指向zip内的asc文件）
139	            Cell convertFileCell = dataRow.createCell(1);
140	            String convertFileName = data.getConvertFileName();
141	            convertFileCell.setCellValue(convertFileName != null ? convertFileName : "");
142	            if (convertFileName != null && !convertFileName.isEmpty()
143	                    && data.getConvertStatus() != null
144	                    && data.getConvertStatus() == ConvertStatusEnum.CONVERTED.getCode()) {
145	                Hyperlink hyperlink = creationHelper.createHyperlink(HyperlinkType.FILE);
146	                hyperlink.setAddress("./" + convertFileName);
147	                convertFileCell.setHyperlink(hyperlink);
148	                convertFileCell.setCellStyle(linkStyle);
149	            }
150	
151	            // 开始时间
152	            dataRow.createCell(2).setCellValue(
153	                    data.getStartTime() != null ? sdf.format(data.getStartTime()) : "");
154	            // 结束时间
155	            dataRow.createCell(3).setCellValue(
156	                    data.getEndTime() != null ? sdf.format(data.getEndTime()) : "");
157	        }
