39	@Slf4j
40	public class CanRecordFileServiceImpl implements CanRecordFileService {
41	    private final CanRecordFileDao canTaskDetailDao;
42	    private final CosConfig cosConfig;
43	
44	    /**
45	     * CAN数据任务详情查询
46	     *
47	     * @param query CAN数据任务详情查询参数
