67	    /**
68	     * 任务转换
69	     * 状态机：0(未转换) → 2(转换中) → 1(已完成)
70	     *                          ↓
71	     *                       3(失败) → 重试时回到 2
72	     *
73	     * @param query
74	     */
75	    @Override
76	    public void recordFileConvert(CanRecordFileQuery query) {
77	        if (query.getIds() == null || query.getIds().isEmpty()) {
78	            throw new RuntimeException("请选择任务");
79	        }
80	
81	        // 逐条处理，单条失败不影响其他任务
82	        for (Long id : query.getIds()) {
83	            // 获得对应的CAN任务详情
