88	            }
89	
90	            // 前置状态检查：仅允许 0(未转换) 和 3(失败) 的任务进入转换
91	            int currentStatus = canRecordFile.getConvertStatus();
92	            if (currentStatus == ConvertStatusEnum.CONVERTING.getCode()) {
93	                log.warn("任务正在转换中，跳过，任务ID: {}", id);
94	                continue;
95	            }
96	            if (currentStatus == ConvertStatusEnum.CONVERTED.getCode()) {
97	                log.warn("任务已完成转换，跳过，任务ID: {}", id);
98	                continue;
99	            }
100	
101	            // 更新状态为转换中
102	            canTaskDetailDao.updateConvertStatus(id, ConvertStatusEnum.CONVERTING.getCode());
103	
104	            // 获得原始文件名（含路径）
105	            String fileName = canRecordFile.getFileName();
106	            log.info("任务状态更新为转换中，开始处理文件: {}, 任务ID: {}", fileName, id);
107	
108	            try {
109	                // 1. 从COS读取压缩文件
110	                String originalCosKey = cosConfig.getOriginalDir() + fileName;
111	                String bucketName = cosConfig.getBucketName();
112	                byte[] compressedData = CosFileDownloader.downloadFromCos(bucketName, originalCosKey);
113	
114	                // 2. 解压
115	                byte[] decompressedData = ZstdUtils.decompressZstd(compressedData);
116	                log.info("COS文件下载解压完成，下载: {} 字节, 解压后: {} 字节", compressedData.length, decompressedData.length);
117	
118	                // 3. 按协议解析
119	                log.info("开始解析数据");
120	                ByteBuffer buffer = ByteBuffer.wrap(decompressedData);
121	                List<DecodeC8Result> results = new ArrayList<>();
122	                Map<String, Integer> dataFrameIdCountMap = new HashMap<>();
123	                int length = 1;
124	
125	                while (buffer.hasRemaining()) {
126	                    try {
127	                        int dataLength = buffer.get();
128	                        // 每1000行输出一次进度
129	                        if (length % 1000 == 0) {
130	                            log.info("已解析 {} 行", length);
131	                        }
132	                        // 检查剩余字节是否足够
133	                        if (buffer.remaining() < dataLength) {
134	                            log.warn("数据长度声明为{}字节，但剩余字节只有{}字节，退出循环", dataLength, buffer.remaining());
135	                            break;
136	                        }
137	
138	                        // 截取dataLength长度的报文
139	                        byte[] messageBytes = new byte[dataLength];
140	                        buffer.get(messageBytes);
141	
142	                        // 构造TboxMessagePlus对象
143	                        TboxMessagePlus messageObj = new TboxMessagePlus();
144	                        messageObj.setMessageBytesUnescaped(messageBytes);
145	
146	                        log.debug("内容原始报文：{}", ByteUtils.byteArrayToHexString(messageObj.getMessageBytesUnescaped()));
147	                        // 调用解析方法
148	                        DecodeC8Result decodeC8Result = TboxTspProtocolDecoder.decodeDataItemsC8(messageObj);
149	
150	                        // 处理解析结果
151	                        results.add(decodeC8Result);
152	
153	                        length++;
154	
155	                        // 统计dataFrameId
156	                        String dataFrameId = decodeC8Result.getDataFrameId();
157	                        if (dataFrameId != null && !dataFrameId.isEmpty()) {
158	                            dataFrameIdCountMap.put(dataFrameId, dataFrameIdCountMap.getOrDefault(dataFrameId, 0) + 1);
159	                        }
160	                    } catch (Exception e) {
161	                        log.error("解析事后录制事件报文失败，第{}行出现异常", length, e);
162	                        // 标记为失败状态并继续处理下一个任务
163	                        canTaskDetailDao.updateConvertStatus(id, ConvertStatusEnum.FAILED.getCode());
164	                        log.info("任务状态更新为失败，任务ID: {}", id);
165	                        // 跳出内层循环，进入外层循环的下一个任务
166	                        throw e;
167	                    }
168	                }
169	
170	                log.info("共解析到 {} 行数据", length - 1);
171	
172	                // 输出dataFrameId统计
173	                log.debug("================== dataFrameId 统计 ==================");
174	                for (Map.Entry<String, Integer> entry : dataFrameIdCountMap.entrySet()) {
175	                    log.debug("dataFrameId: {} , 采集行数: {}", entry.getKey(), entry.getValue());
176	                }
177	                log.debug("====================================================");
178	
179	                // 转换为asc文件格式
180	                CanToAscConverter converter = new CanToAscConverter();
181	                // 创建临时目录，在模块根目录下创建
182	                File tempDir = new File(System.getProperty("user.dir") + "/temp");
183	                if (!tempDir.exists()) {
184	                    tempDir.mkdirs();
185	                }
186	
187	                // 设置临时路径
188	                String outputPath = tempDir.getAbsolutePath() + File.separator + fileName + ".asc";
189	
190	                converter.convertToAsc(results, outputPath);
191	
192	                // 构建转换后的文件名（将 .zst 后缀替换为 .asc）
193	                String convertFileName = fileName.replaceAll("\\.zst$", ".asc");
194	
195	                // 上传ASC文件到COS
196	                File ascFile = new File(outputPath);
197	                if (!ascFile.exists()) {
198	                    throw new RuntimeException("ASC文件不存在: " + outputPath);
199	                }
200	                String convertCosKey = cosConfig.getConvertedDir() + convertFileName;
201	                CosFileDownloader.putFile(bucketName, convertCosKey, ascFile);
202	
203	                // 更新转换后文件名
204	                canRecordFile.setConvertFileName(convertFileName);
205	                canTaskDetailDao.updateById(canRecordFile);
206	                log.info("文件转换上传完成，任务ID: {}, 转换文件: {}, COS: {}", id, convertFileName, convertCosKey);
207	
208	                // 上传完成，删除临时文件
209	                if (ascFile.exists()) {
210	                    ascFile.delete();
211	                    log.debug("临时文件已删除: {}", outputPath);
212	                }
213	
214	                // 更新任务状态为已完成
215	                canTaskDetailDao.updateConvertStatus(id, ConvertStatusEnum.CONVERTED.getCode());
216	                log.info("任务转换完成，任务ID: {}", id);
217	
218	            } catch (Exception e) {
219	                log.error("任务转换失败，任务ID: {}, 错误: {}", id, e.getMessage(), e);
220	                // 外层转换失败也设置状态，作用于文件下载失败的情况
221	                canTaskDetailDao.updateConvertStatus(id, ConvertStatusEnum.FAILED.getCode());
222	            }
223	        }
224	    }
