                        DecodeC8Result decodeC8Result = TboxTspProtocolDecoder.decodeDataItemsC8(messageObj);

                        // 处理解析结果
                        results.add(decodeC8Result);

                        length++;

                        // 统计dataFrameId
                        String dataFrameId = decodeC8Result.getDataFrameId();
                        if (dataFrameId != null && !dataFrameId.isEmpty()) {
                            dataFrameIdCountMap.put(dataFrameId, dataFrameIdCountMap.getOrDefault(dataFrameId, 0) + 1);
                        }
                    } catch (Exception e) {
                        log.error("解析事后录制事件报文失败，第{}行出现异常", length, e);
                        // 标记为失败状态并继续处理下一个任务
                        canTaskDetailDao.updateConvertStatus(id, ConvertStatusEnum.FAILED.getCode());
                        log.info("任务状态更新为失败，任务ID: {}", id);
                        // 跳出内层循环，进入外层循环的下一个任务
                        throw e;
                    }
                }

                log.info("共解析到 {} 行数据", length - 1);

                // 输出dataFrameId统计
                log.debug("================== dataFrameId 统计 ==================");
                for (Map.Entry<String, Integer> entry : dataFrameIdCountMap.entrySet()) {
                    log.debug("dataFrameId: {} , 采集行数: {}", entry.getKey(), entry.getValue());
                }
                log.debug("====================================================");

                // 转换为asc文件格式
                CanToAscConverter converter = new CanToAscConverter();
                // 创建临时目录，在模块根目录下创建
                File tempDir = new File(System.getProperty("user.dir") + "/temp");
                if (!tempDir.exists()) {
                    tempDir.mkdirs();
                }

                // 设置临时路径
                String outputPath = tempDir.getAbsolutePath() + File.separator + fileName + ".asc";

                converter.convertToAsc(results, outputPath);

                // 构建转换后的文件名（将 .zst 后缀替换为 .asc）
                String convertFileName = fileName.replaceAll("\\.zst$", ".asc");

                // 上传ASC文件到COS
                File ascFile = new File(outputPath);
                if (!ascFile.exists()) {
                    throw new RuntimeException("ASC文件不存在: " + outputPath);
                }
                String convertCosKey = cosConfig.getConvertedDir() + convertFileName;
                CosFileDownloader.putFile(bucketName, convertCosKey, ascFile);

                // 更新转换后文件名
                canRecordFile.setConvertFileName(convertFileName);
                canTaskDetailDao.updateById(canRecordFile);
                log.info("文件转换上传完成，任务ID: {}, 转换文件: {}, COS: {}", id, convertFileName, convertCosKey);

                // 上传完成，删除临时文件
                if (ascFile.exists()) {
                    ascFile.delete();
                    log.debug("临时文件已删除: {}", outputPath);
                }

                // 更新任务状态为已完成
                canTaskDetailDao.updateConvertStatus(id, ConvertStatusEnum.CONVERTED.getCode());
                log.info("任务转换完成，任务ID: {}", id);

            } catch (Exception e) {
                log.error("任务转换失败，任务ID: {}, 错误: {}", id, e.getMessage(), e);
                // 外层转换失败也设置状态，作用于文件下载失败的情况
                canTaskDetailDao.updateConvertStatus(id, ConvertStatusEnum.FAILED.getCode());
            }
        }
    }

    /**
     * 查询数据（导出用）
     *
     * @param query
     * @return CAN数据任务详情实体列表
     */
    @Override
    public List<CanRecordFile> selectData(CanRecordFileQuery query) {
        return canTaskDetailDao.selectCanRecordFileListForExport(query);
    }

    /**
     * 添加CAN数据任务详情
     *
     * @param dto 新增文件请求参数
     */
    @Override
    public void add(AddFileDTO dto) {
        CanRecordFile canRecordFile = new CanRecordFile();
        BeanUtils.copyProperties(dto, canRecordFile);
        canTaskDetailDao.insert(canRecordFile);
    }
}

