81	    /**
82	     * 更新清除时间
83	     * @param dto 更新清除时间请求参数
84	     */
85	    @Override
86	    public void updateClearTime(UpdateClearTimeDTO dto) {
87	        CanRecordTask canTask = new CanRecordTask();
88	        BeanUtils.copyProperties(dto, canTask);
89	        canTaskDao.updateClearTime(canTask);
90	    }
91	
92	    /**
93	     * 删除CAN数据录制任务
94	     *
95	     * @param id
96	     */
97	    @Override
98	    @Transactional(rollbackFor = Exception.class)
99	    public Response delete(Long id) {
100	        CanRecordTask task = canTaskDao.selectById(id);
101	        if (task == null) {
102	            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_QUERY_FAILED, "任务不存在"));
103	        }
104	        if (!Integer.valueOf(TaskStatusEnum.ENDED.getCode()).equals(task.getStatus())) {
105	            return Response.error(ErrorWithExtra.of(DataExportManagerError.UNEXPECTED_TASK_STATUS, "仅已结束的录制任务允许删除"));
106	        }
107	
108	        try {
109	            List<CanRecordFile> recordFiles = canRecordFileDao.selectByTaskId(id);
110	            deleteRecordFilesFromCos(id, recordFiles);
111	        } catch (Exception e) {
112	            log.error("删除CAN录制任务关联文件失败，taskId={}", id, e);
113	            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_UPDATE_FAILED, "删除录制任务关联文件失败"));
114	        }
115	
116	        canRecordFileDao.deleteByTaskIds(Collections.singletonList(id));
117	        canTaskDao.delete(id);
118	        log.info("CAN录制任务删除完成，taskId={}", id);
119	        return Response.success();
120	    }
121	
122	    /**
123	     * 创建CAN数据录制任务
124	     *
125	     * @param dto 创建任务参数
126	     */
127	    @Override
128	    public void create(CreateTaskDTO dto) {
129	        CanRecordTask canTask = new CanRecordTask();
130	        BeanUtils.copyProperties(dto, canTask);
131	        initNewTaskDefaults(canTask);
132	        // 拼装canMessage字段：msgId(msgName),msgId(msgName),...
133	        List<CanMsgVo> canMsgList = dto.getCanMsgList();
134	        if (canMsgList != null && !canMsgList.isEmpty()) {
135	            String canMessage = canMsgList.stream()
136	                    .map(msg -> msg.getMsgId() + "(" + msg.getMsgName() + ")")
137	                    .collect(Collectors.joining(","));
138	            canTask.setCanMessage(canMessage);
139	        }
140	        canTaskDao.insert(canTask);
141	    }
142	
143	    /**
144	     * 复制CAN数据录制任务
145	     *
146	     * @param dto 复制任务请求参数
147	     */
148	    @Override
149	    public void copy(CopyTaskDTO dto) {
150	        CanRecordTask canTask = new CanRecordTask();
151	        BeanUtils.copyProperties(dto, canTask);
152	        initNewTaskDefaults(canTask);
153	        canTaskDao.insert(canTask);
154	    }
155	
156	    private void initNewTaskDefaults(CanRecordTask canTask) {
157	        canTask.setStatus(TaskStatusEnum.NOT_STARTED.getCode());
158	        canTask.setClearTime(buildDefaultClearTime());
159	    }
160	
161	    private Date buildDefaultClearTime() {
162	        Calendar calendar = Calendar.getInstance();
163	        calendar.add(Calendar.DAY_OF_MONTH, DEFAULT_CLEAR_DAYS);
164	        return calendar.getTime();
165	    }
166	
167	    /**
168	     * 更新状态（API调用，包含下行指令发送）
169	     *
170	     * @param dto 更新状态参数
171	     * @return 操作结果
172	     */
173	    @Override
174	    public Response updateStatus(UpdateStatusDTO dto) {
175	        // 查询当前任务信息
176	        CanRecordTask currentTask = canTaskDao.selectById(dto.getId());
177	        if (currentTask == null) {
178	            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_QUERY_FAILED, "任务不存在"));
179	        }
180	
181	        Integer status = dto.getStatus();
182	        // 发送下行指令（启动或停止）
183	        if (Integer.valueOf(TaskStatusEnum.STARTING.getCode()).equals(status)) {
184	            // 启动录制任务
185	            Response result = sendStartCommand(currentTask);
186	            if (result != null) {
187	                return result;
188	            }
189	        } else if (Integer.valueOf(TaskStatusEnum.STOPPING.getCode()).equals(status)) {
190	            // 停止录制任务
191	            Response result = sendStopCommand(currentTask);
192	            if (result != null) {
193	                return result;
194	            }
195	        }
196	
197	        // 下发成功后状态需变更
198	        CanRecordTask updateTask = new CanRecordTask();
199	        updateTask.setId(dto.getId());
200	        updateTask.setStatus(status);
201	        updateTask.setUserId(dto.getUserId());
202	        updateTask.setUserName(dto.getUserName());
203	        canTaskDao.updateStatus(updateTask);
204	        return Response.success();
205	    }
206	
207	    /**
208	     * 直接更新任务状态（不发送下行指令）
209	     * 用于Kafka消息回调等内部状态同步场景
210	     *
211	     * @param canTask 包含id和status的任务对象
212	     */
213	    @Override
214	    public void updateStatusDirect(CanRecordTask canTask) {
215	        if (canTask == null || canTask.getId() == null) {
216	            log.warn("更新状态失败：任务对象或ID为空");
217	            return;
218	        }
219	        canTaskDao.updateStatus(canTask);
220	    }
221	
222	    /**
223	     * 发送启动录制指令
224	     *
225	     * @param task 当前任务
226	     * @return 如果失败返回错误响应，成功返回 null
227	     */
228	    private Response sendStartCommand(CanRecordTask task) {
229	        // 解析canMessage中的msgId列表，查询完整报文信息
230	        List<CanMsgVo> canMsgList = queryCanMsgListFromTask(task);
231	
232	        Map<String, Object> downlinkParams = new HashMap<>();
233	        downlinkParams.put("commandId", CommandEnum.START.getCode());
234	        downlinkParams.put("taskId", task.getId());
235	        downlinkParams.put("recordDuration", task.getDuration() * 60);
236	
237	        // 构建CAN报文信息列表
238	        if (canMsgList != null && !canMsgList.isEmpty()) {
239	            List<CanMessageInfo> canMessageInfoList = canMsgList.stream()
240	                    .map(msg -> {
241	                        CanMessageInfo info = new CanMessageInfo();
242	                        info.setMsgIdHex(msg.getMsgId());
243	                        info.setMsgLength(msg.getMsgLength());
244	                        return info;
245	                    })
246	                    .collect(Collectors.toList());
247	            downlinkParams.put("canMessageCount", canMessageInfoList.size());
248	            downlinkParams.put("canMessageInfoList", canMessageInfoList);
249	        }
250	
251	        return sendDownlinkCommand(task.getVin(), downlinkParams);
252	    }
253	
254	    /**
255	     * 发送停止录制指令
256	     *
257	     * @param task 当前任务
258	     * @return 如果失败返回错误响应，成功返回 null
259	     */
260	    private Response sendStopCommand(CanRecordTask task) {
261	        Map<String, Object> downlinkParams = new HashMap<>();
262	        downlinkParams.put("commandId", CommandEnum.STOP.getCode());
263	        downlinkParams.put("taskId", task.getId());
264	        return sendDownlinkCommand(task.getVin(), downlinkParams);
265	    }
266	
267	    /**
268	     * 发送下行指令到 downlink-command-dispatcher
269	     *
270	     * @param vin            车辆VIN
271	     * @param downlinkParams 下行参数
272	     * @return 如果失败返回错误响应，成功返回 null
273	     */
274	    private Response sendDownlinkCommand(String vin, Map<String, Object> downlinkParams) {
275	        DownlinkParamVo downlinkParamVo = new DownlinkParamVo();
276	        downlinkParamVo.setVin(vin);
277	        downlinkParamVo.setOperationTime(System.currentTimeMillis());
278	        downlinkParamVo.setDownlinkParamsJsonStr(JsonUtil.writeValueAsString(downlinkParams));
279	
280	        BaseResult baseResult = downlinkCommandDispatcher.recordControlCommandsAfterwards(downlinkParamVo);
281	        // 检查返回结果
282	        if (baseResult == null) {
283	            log.error("recordControlCommandsAfterwards 返回 null");
284	            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_UPDATE_FAILED, "下行指令调用失败"));
285	        }
286	        if (baseResult.getResultCode() != 0) {
287	            log.error("recordControlCommandsAfterwards resp, msgCode: {}, msg: {}",
288	                    baseResult.getMessageCode(), baseResult.getMessage());
289	            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_UPDATE_FAILED, baseResult.getMessage()));
290	        }
291	        return null;
292	    }
293	
294	    /**
295	     * 从任务的canMessage字段解析msgId列表，查询完整CAN报文信息
296	     */
297	    private List<CanMsgVo> queryCanMsgListFromTask(CanRecordTask task) {
298	        String canMessage = task.getCanMessage();
299	        if (canMessage == null || canMessage.isEmpty()) {
300	            return Collections.emptyList();
301	        }
302	        List<String> msgIds = new ArrayList<>();
303	        String[] parts = canMessage.split(",");
304	        for (String part : parts) {
305	            int parenIdx = part.indexOf("(");
306	            if (parenIdx > 0) {
307	                msgIds.add(part.substring(0, parenIdx));
308	            } else {
309	                msgIds.add(part.trim());
310	            }
311	        }
312	        if (msgIds.isEmpty()) {
313	            return Collections.emptyList();
314	        }
315	        return canTaskDao.queryCanMsgByMsgIds(task.getVin(), msgIds);
316	    }
317	
318	    /**
319	     * 查询CAN数据录制任务数量
320	     *
321	     * @param query 查询条件
322	     * @return 任务数量
323	     */
324	    @Override
325	    public int getCount(CanRecordTaskQuery query) {
326	        return canTaskDao.getCount(query);
327	    }
328	
329	    /**
330	     * 查询CAN报文
331	     *
332	     * @param query 查询条件
333	     * @param page  分页参数
334	     * @return CAN报文列表
335	     */
336	    @Override
337	    public List<CanMsgVo> queryCanMsg(CanRecordTaskQuery query, Page page) {
338	        return canTaskDao.queryCanMsg(query, page);
339	    }
340	
341	    /**
342	     * 根据清除时间批量删除过期任务、关联文件记录和COS文件
343	     */
344	    @Override
345	    @Transactional(rollbackFor = Exception.class)
346	    public void deleteByClearTime() {
347	        List<CanRecordTask> expiredTasks = canTaskDao.selectExpiredClearTimeList();
348	        if (expiredTasks == null || expiredTasks.isEmpty()) {
349	            log.info("未查询到需要清理的过期CAN录制任务");
350	            return;
351	        }
352	
353	        List<Long> clearedTaskIds = new ArrayList<>();
354	        for (CanRecordTask task : expiredTasks) {
355	            if (task == null || task.getId() == null) {
356	                continue;
357	            }
358	            Long taskId = task.getId();
359	            try {
360	                List<CanRecordFile> recordFiles = canRecordFileDao.selectByTaskId(taskId);
361	                deleteRecordFilesFromCos(taskId, recordFiles);
362	                clearedTaskIds.add(taskId);
363	            } catch (Exception e) {
364	                log.error("清理过期CAN录制任务文件失败，本次跳过数据库删除，taskId={}", taskId, e);
365	            }
366	        }
367	
368	        if (clearedTaskIds.isEmpty()) {
369	            log.warn("过期CAN录制任务文件均未清理成功，本次不删除数据库记录，待下次定时任务重试");
370	            return;
371	        }
372	
373	        canRecordFileDao.deleteByTaskIds(clearedTaskIds);
374	        canTaskDao.deleteByIds(clearedTaskIds);
375	        log.info("过期CAN录制任务清理完成，待清理任务数：{}，成功清理任务数：{}",
376	                expiredTasks.size(), clearedTaskIds.size());
377	    }
378	
379	    private void deleteRecordFilesFromCos(Long taskId, List<CanRecordFile> recordFiles) {
380	        if (recordFiles == null || recordFiles.isEmpty()) {
381	            log.info("过期CAN录制任务无关联录制文件，taskId={}", taskId);
382	            return;
383	        }
384	
385	        Set<String> originalFileKeys = new LinkedHashSet<>();
386	        Set<String> convertedFileKeys = new LinkedHashSet<>();
387	        for (CanRecordFile recordFile : recordFiles) {
388	            if (recordFile == null) {
389	                continue;
390	            }
391	            String originalFileKey = buildCosKey(cosConfig.getOriginalDir(), recordFile.getFileName());
392	            if (originalFileKey != null) {
393	                originalFileKeys.add(originalFileKey);
394	            }
395	            String convertedFileKey = buildCosKey(cosConfig.getConvertedDir(), recordFile.getConvertFileName());
396	            if (convertedFileKey != null) {
397	                convertedFileKeys.add(convertedFileKey);
398	            }
399	        }
400	
401	        for (String originalFileKey : originalFileKeys) {
402	            CosFileDownloader.deleteFile(cosConfig.getBucketName(), originalFileKey);
403	        }
404	        for (String convertedFileKey : convertedFileKeys) {
405	            CosFileDownloader.deleteFile(cosConfig.getBucketName(), convertedFileKey);
406	        }
407	        log.info("过期CAN录制任务关联COS文件清理完成，taskId={}, 原始文件数={}, 转换文件数={}",
408	                taskId, originalFileKeys.size(), convertedFileKeys.size());
409	    }
410	
411	    private String buildCosKey(String dir, String fileName) {
412	        if (!hasText(fileName)) {
413	            return null;
414	        }
415	        if (!hasText(dir)) {
416	            return fileName;
417	        }
418	        return dir.endsWith("/") ? dir + fileName : dir + "/" + fileName;
419	    }
420	
421	    private boolean hasText(String value) {
422	        return value != null && !value.trim().isEmpty();
423	    }
424	
425	    /**
426	     * 查询可用VIN（暂定）
427	     *
428	     * @return
429	     */
430	    @Override
431	    public List<String> queryAvailableVin() {
432	        return canTaskDao.queryAvailableVin();
433	    }
434	
435	    /**
436	     * 根据VIN查询矩阵平台列表
437	     *
