package com.ne.business.dflq.can.service.Impl;

import com.ne.boot.common.entity.Page;
import com.ne.boot.common.entity.Response;
import com.ne.business.dflq.can.config.CosConfig;
import com.ne.business.dflq.can.dao.CanRecordFileDao;
import com.ne.business.dflq.can.dao.CanRecordTaskDao;
import com.ne.business.dflq.can.entity.BaseResult;
import com.ne.business.dflq.can.entity.CanRecordFile;
import com.ne.business.dflq.can.entity.CanRecordTask;
import com.ne.business.dflq.can.entity.dto.CopyTaskDTO;
import com.ne.business.dflq.can.entity.dto.CreateTaskDTO;
import com.ne.business.dflq.can.entity.dto.UpdateClearTimeDTO;
import com.ne.business.dflq.can.entity.dto.UpdateStatusDTO;
import com.ne.business.dflq.can.entity.query.CanRecordTaskQuery;
import com.ne.business.dflq.can.entity.vo.CanMsgVo;
import com.ne.business.dflq.can.entity.vo.MatrixPlatformVo;
import com.ne.business.dflq.can.enums.CommandEnum;
import com.ne.business.dflq.can.enums.TaskStatusEnum;
import com.ne.business.dflq.can.error.DataExportManagerError;
import com.ne.business.dflq.can.error.ErrorWithExtra;
import com.ne.business.dflq.can.feign.DownlinkCommandDispatcher;
import com.ne.business.dflq.can.service.CanRecordTaskService;
import com.ne.business.dflq.can.utils.CosFileDownloader;
import com.ne.ice.mix.protocol.util.JsonUtil;
import com.ne.ice.tbox.protocol.dto.CanMessageInfo;
import com.ne.ice.tbox.protocol.dto.DownlinkParamVo;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.BeanUtils;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;
import java.util.stream.Collectors;

/**
 * CAN数据任务服务层实现类
 *
 * @author weihong
 * @date 2026-2-26
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class CanRecordTaskServiceImpl implements CanRecordTaskService {

    private static final int DEFAULT_CLEAR_DAYS = 90;

    private final CanRecordTaskDao canTaskDao;

    private final CanRecordFileDao canRecordFileDao;

    private final CosConfig cosConfig;

    private final DownlinkCommandDispatcher downlinkCommandDispatcher;

    /**
    * 查询CAN数据录制任务
     * @param query
     * @param page
     * @return
     */
    @Override
    public List<CanRecordTask> query(CanRecordTaskQuery query, Page page) {
        return canTaskDao.query(query, page);
    }

    /**
     * 根据ID查询CAN数据录制任务
     *
     * @param id 任务ID
     * @return 任务实体
     */
    @Override
    public CanRecordTask getById(Long id) {
        return canTaskDao.selectById(id);
    }

    /**
     * 更新清除时间
     * @param dto 更新清除时间请求参数
     */
    @Override
    public void updateClearTime(UpdateClearTimeDTO dto) {
        CanRecordTask canTask = new CanRecordTask();
        BeanUtils.copyProperties(dto, canTask);
        canTaskDao.updateClearTime(canTask);
    }

    /**
     * 删除CAN数据录制任务
     *
     * @param id
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public Response delete(Long id) {
        CanRecordTask task = canTaskDao.selectById(id);
        if (task == null) {
            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_QUERY_FAILED, "任务不存在"));
        }
        if (!Integer.valueOf(TaskStatusEnum.ENDED.getCode()).equals(task.getStatus())) {
            return Response.error(ErrorWithExtra.of(DataExportManagerError.UNEXPECTED_TASK_STATUS, "仅已结束的录制任务允许删除"));
        }

        try {
            List<CanRecordFile> recordFiles = canRecordFileDao.selectByTaskId(id);
            deleteRecordFilesFromCos(id, recordFiles);
        } catch (Exception e) {
            log.error("删除CAN录制任务关联文件失败，taskId={}", id, e);
            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_UPDATE_FAILED, "删除录制任务关联文件失败"));
        }

        canRecordFileDao.deleteByTaskIds(Collections.singletonList(id));
        canTaskDao.delete(id);
        log.info("CAN录制任务删除完成，taskId={}", id);
        return Response.success();
    }

    /**
     * 创建CAN数据录制任务
     *
     * @param dto 创建任务参数
     */
    @Override
    public void create(CreateTaskDTO dto) {
        CanRecordTask canTask = new CanRecordTask();
        BeanUtils.copyProperties(dto, canTask);
        initNewTaskDefaults(canTask);
        // 拼装canMessage字段：msgId(msgName),msgId(msgName),...
        List<CanMsgVo> canMsgList = dto.getCanMsgList();
        if (canMsgList != null && !canMsgList.isEmpty()) {
            String canMessage = canMsgList.stream()
                    .map(msg -> msg.getMsgId() + "(" + msg.getMsgName() + ")")
                    .collect(Collectors.joining(","));
            canTask.setCanMessage(canMessage);
        }
        canTaskDao.insert(canTask);
    }

    /**
     * 复制CAN数据录制任务
     *
     * @param dto 复制任务请求参数
     */
    @Override
    public void copy(CopyTaskDTO dto) {
        CanRecordTask canTask = new CanRecordTask();
        BeanUtils.copyProperties(dto, canTask);
        initNewTaskDefaults(canTask);
        canTaskDao.insert(canTask);
    }

    private void initNewTaskDefaults(CanRecordTask canTask) {
        canTask.setStatus(TaskStatusEnum.NOT_STARTED.getCode());
        canTask.setClearTime(buildDefaultClearTime());
    }

    private Date buildDefaultClearTime() {
        Calendar calendar = Calendar.getInstance();
        calendar.add(Calendar.DAY_OF_MONTH, DEFAULT_CLEAR_DAYS);
        return calendar.getTime();
    }

    /**
     * 更新状态（API调用，包含下行指令发送）
     *
     * @param dto 更新状态参数
     * @return 操作结果
     */
    @Override
    public Response updateStatus(UpdateStatusDTO dto) {
        // 查询当前任务信息
        CanRecordTask currentTask = canTaskDao.selectById(dto.getId());
        if (currentTask == null) {
            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_QUERY_FAILED, "任务不存在"));
        }

        Integer status = dto.getStatus();
        // 发送下行指令（启动或停止）
        if (Integer.valueOf(TaskStatusEnum.STARTING.getCode()).equals(status)) {
            // 启动录制任务
            Response result = sendStartCommand(currentTask);
            if (result != null) {
                return result;
            }
        } else if (Integer.valueOf(TaskStatusEnum.STOPPING.getCode()).equals(status)) {
            // 停止录制任务
            Response result = sendStopCommand(currentTask);
            if (result != null) {
                return result;
            }
        }

        // 下发成功后状态需变更
        CanRecordTask updateTask = new CanRecordTask();
        updateTask.setId(dto.getId());
        updateTask.setStatus(status);
        updateTask.setUserId(dto.getUserId());
        updateTask.setUserName(dto.getUserName());
        canTaskDao.updateStatus(updateTask);
        return Response.success();
    }

    /**
     * 直接更新任务状态（不发送下行指令）
     * 用于Kafka消息回调等内部状态同步场景
     *
     * @param canTask 包含id和status的任务对象
     */
    @Override
    public void updateStatusDirect(CanRecordTask canTask) {
        if (canTask == null || canTask.getId() == null) {
            log.warn("更新状态失败：任务对象或ID为空");
            return;
        }
        canTaskDao.updateStatus(canTask);
    }

    /**
     * 发送启动录制指令
     *
     * @param task 当前任务
     * @return 如果失败返回错误响应，成功返回 null
     */
    private Response sendStartCommand(CanRecordTask task) {
        // 解析canMessage中的msgId列表，查询完整报文信息
        List<CanMsgVo> canMsgList = queryCanMsgListFromTask(task);

        Map<String, Object> downlinkParams = new HashMap<>();
        downlinkParams.put("commandId", CommandEnum.START.getCode());
        downlinkParams.put("taskId", task.getId());
        downlinkParams.put("recordDuration", task.getDuration() * 60);

        // 构建CAN报文信息列表
        if (canMsgList != null && !canMsgList.isEmpty()) {
            List<CanMessageInfo> canMessageInfoList = canMsgList.stream()
                    .map(msg -> {
                        CanMessageInfo info = new CanMessageInfo();
                        info.setMsgIdHex(msg.getMsgId());
                        info.setMsgLength(msg.getMsgLength());
                        return info;
                    })
                    .collect(Collectors.toList());
            downlinkParams.put("canMessageCount", canMessageInfoList.size());
            downlinkParams.put("canMessageInfoList", canMessageInfoList);
        }

        return sendDownlinkCommand(task.getVin(), downlinkParams);
    }

    /**
     * 发送停止录制指令
     *
     * @param task 当前任务
     * @return 如果失败返回错误响应，成功返回 null
     */
    private Response sendStopCommand(CanRecordTask task) {
        Map<String, Object> downlinkParams = new HashMap<>();
        downlinkParams.put("commandId", CommandEnum.STOP.getCode());
        downlinkParams.put("taskId", task.getId());
        return sendDownlinkCommand(task.getVin(), downlinkParams);
    }

    /**
     * 发送下行指令到 downlink-command-dispatcher
     *
     * @param vin            车辆VIN
     * @param downlinkParams 下行参数
     * @return 如果失败返回错误响应，成功返回 null
     */
    private Response sendDownlinkCommand(String vin, Map<String, Object> downlinkParams) {
        DownlinkParamVo downlinkParamVo = new DownlinkParamVo();
        downlinkParamVo.setVin(vin);
        downlinkParamVo.setOperationTime(System.currentTimeMillis());
        downlinkParamVo.setDownlinkParamsJsonStr(JsonUtil.writeValueAsString(downlinkParams));

        BaseResult baseResult = downlinkCommandDispatcher.recordControlCommandsAfterwards(downlinkParamVo);
        // 检查返回结果
        if (baseResult == null) {
            log.error("recordControlCommandsAfterwards 返回 null");
            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_UPDATE_FAILED, "下行指令调用失败"));
        }
        if (baseResult.getResultCode() != 0) {
            log.error("recordControlCommandsAfterwards resp, msgCode: {}, msg: {}",
                    baseResult.getMessageCode(), baseResult.getMessage());
            return Response.error(ErrorWithExtra.of(DataExportManagerError.TASK_UPDATE_FAILED, baseResult.getMessage()));
        }
        return null;
    }

    /**
     * 从任务的canMessage字段解析msgId列表，查询完整CAN报文信息
     */
    private List<CanMsgVo> queryCanMsgListFromTask(CanRecordTask task) {
        String canMessage = task.getCanMessage();
        if (canMessage == null || canMessage.isEmpty()) {
            return Collections.emptyList();
        }
        List<String> msgIds = new ArrayList<>();
        String[] parts = canMessage.split(",");
        for (String part : parts) {
            int parenIdx = part.indexOf("(");
            if (parenIdx > 0) {
                msgIds.add(part.substring(0, parenIdx));
            } else {
                msgIds.add(part.trim());
            }
        }
        if (msgIds.isEmpty()) {
            return Collections.emptyList();
        }
        return canTaskDao.queryCanMsgByMsgIds(task.getVin(), msgIds);
    }

    /**
     * 查询CAN数据录制任务数量
     *
     * @param query 查询条件
     * @return 任务数量
     */
    @Override
    public int getCount(CanRecordTaskQuery query) {
        return canTaskDao.getCount(query);
    }

    /**
     * 查询CAN报文
     *
     * @param query 查询条件
     * @param page  分页参数
     * @return CAN报文列表
     */
    @Override
    public List<CanMsgVo> queryCanMsg(CanRecordTaskQuery query, Page page) {
        return canTaskDao.queryCanMsg(query, page);
    }

    /**
     * 根据清除时间批量删除过期任务、关联文件记录和COS文件
     */
    @Override
    @Transactional(rollbackFor = Exception.class)
    public void deleteByClearTime() {
        List<CanRecordTask> expiredTasks = canTaskDao.selectExpiredClearTimeList();
        if (expiredTasks == null || expiredTasks.isEmpty()) {
            log.info("未查询到需要清理的过期CAN录制任务");
            return;
        }

        List<Long> clearedTaskIds = new ArrayList<>();
        for (CanRecordTask task : expiredTasks) {
            if (task == null || task.getId() == null) {
                continue;
            }
            Long taskId = task.getId();
            try {
                List<CanRecordFile> recordFiles = canRecordFileDao.selectByTaskId(taskId);
                deleteRecordFilesFromCos(taskId, recordFiles);
                clearedTaskIds.add(taskId);
            } catch (Exception e) {
                log.error("清理过期CAN录制任务文件失败，本次跳过数据库删除，taskId={}", taskId, e);
            }
        }

        if (clearedTaskIds.isEmpty()) {
            log.warn("过期CAN录制任务文件均未清理成功，本次不删除数据库记录，待下次定时任务重试");
            return;
        }

        canRecordFileDao.deleteByTaskIds(clearedTaskIds);
        canTaskDao.deleteByIds(clearedTaskIds);
        log.info("过期CAN录制任务清理完成，待清理任务数：{}，成功清理任务数：{}",
                expiredTasks.size(), clearedTaskIds.size());
    }

    private void deleteRecordFilesFromCos(Long taskId, List<CanRecordFile> recordFiles) {
        if (recordFiles == null || recordFiles.isEmpty()) {
            log.info("过期CAN录制任务无关联录制文件，taskId={}", taskId);
            return;
        }

        Set<String> originalFileKeys = new LinkedHashSet<>();
        Set<String> convertedFileKeys = new LinkedHashSet<>();
        for (CanRecordFile recordFile : recordFiles) {
            if (recordFile == null) {
                continue;
            }
            String originalFileKey = buildCosKey(cosConfig.getOriginalDir(), recordFile.getFileName());
            if (originalFileKey != null) {
                originalFileKeys.add(originalFileKey);
            }
            String convertedFileKey = buildCosKey(cosConfig.getConvertedDir(), recordFile.getConvertFileName());
            if (convertedFileKey != null) {
                convertedFileKeys.add(convertedFileKey);
            }
        }

        for (String originalFileKey : originalFileKeys) {
            CosFileDownloader.deleteFile(cosConfig.getBucketName(), originalFileKey);
        }
        for (String convertedFileKey : convertedFileKeys) {
            CosFileDownloader.deleteFile(cosConfig.getBucketName(), convertedFileKey);
        }
        log.info("过期CAN录制任务关联COS文件清理完成，taskId={}, 原始文件数={}, 转换文件数={}",
                taskId, originalFileKeys.size(), convertedFileKeys.size());
    }

    private String buildCosKey(String dir, String fileName) {
        if (!hasText(fileName)) {
            return null;
        }
        if (!hasText(dir)) {
            return fileName;
        }
        return dir.endsWith("/") ? dir + fileName : dir + "/" + fileName;
    }

    private boolean hasText(String value) {
        return value != null && !value.trim().isEmpty();
    }

    /**
     * 查询可用VIN（暂定）
     *
     * @return
     */
    @Override
    public List<String> queryAvailableVin() {
        return canTaskDao.queryAvailableVin();
    }

    /**
     * 根据VIN查询矩阵平台列表
     *
     * @param vin VIN
     * @return 矩阵平台列表
     */
    @Override
    public List<MatrixPlatformVo> queryMatrixPlatform(String vin) {
        return canTaskDao.queryMatrixPlatform(vin);
    }
}

