1	package com.ne.business.dflq.can.utils;
2	
3	import com.ne.ice.tbox.protocol.dto.DecodeC8Result;
4	
5	import java.io.*;
6	import java.text.SimpleDateFormat;
7	import java.util.Date;
8	import java.util.List;
9	import java.util.Locale;
10	
11	/**
12	 * CAN原始数据转ASC格式文件工具类
13	 *
14	 * @author weihong
15	 * @date 2026-4-13
16	 */
17	public class CanToAscConverter {
18	
19	    /**
20	     * 将CAN报文列表转换为ASC格式文件
21	     */
22	    public void convertToAsc(List<DecodeC8Result> frameList, String outputPath) throws IOException {
23	        validateInput(frameList);
24	        Long startTimeMs = frameList.get(0).getAcquisitionTime();
25	        createOutputDirectory(outputPath);
26	        writeAscFile(frameList, outputPath, startTimeMs);
27	    }
28	
29	    /**
30	     * 将单个CAN报文转换为ASC格式的一行
31	     */
32	    private String convertFrameToAscLine(DecodeC8Result frame, Long startTimeMs) {
33	        // 1. 时间差（秒），格式化为xxxx.xxxx
34	        String timeStr = formatTimeDelta(frame.getAcquisitionTime(), startTimeMs);
35	
36	        // 2. 通道号
37	        Integer channel = frame.getChannelNumber();
38	
39	        // 3. 帧ID（根据ID类型添加后缀）
40	        String idStr = formatFrameId(frame.getDataFrameId(), frame.getDataFrameIdType());
41	
42	        // 4. 方向（固定为Rx）
43	        String direction = "Rx";
44	
45	        // 5. 数据长度（DLC）
46	        Integer dlc = frame.getDataFieldLength();
47	
48	        // 6. 格式化数据场 - 关键修复！
49	        String dataField = formatDataField(frame.getDataFieldHex(), dlc);
50	
51	        // 7. 拼接为ASC格式
52	        return String.format("%s %d %s %s d %d %s",
53	                timeStr,
54	                channel,
55	                idStr,
56	                direction,
57	                dlc,
58	                dataField);
59	    }
60	
61	    /**
62	     * 格式化数据场 - 确保每个字节之间有空格分隔
63	     *
64	     * @param dataFieldHex 原始数据场字符串（可能连续或已有空格）
65	     * @param dlc 数据长度
66	     * @return 格式化后的数据场字符串
67	     */
68	    private String formatDataField(String dataFieldHex, Integer dlc) {
69	        if (dataFieldHex == null || dataFieldHex.isEmpty()) {
70	            return "";
71	        }
72	
73	        // 1. 去除所有现有空格，得到纯净的十六进制字符串
74	        String cleanHex = dataFieldHex.replaceAll("\\s+", "");
75	
76	        // 2. 验证长度是否正确（每个字节2个字符）
77	        int expectedLength = dlc * 2;
78	        if (cleanHex.length() != expectedLength) {
79	            // 如果长度不匹配，尝试修复或记录警告
80	            System.err.println("警告: 数据场长度不匹配，期望: " + expectedLength +
81	                    "，实际: " + cleanHex.length() + "，数据: " + dataFieldHex);
82	
83	            // 如果太长，截断；如果太短，补0
84	            if (cleanHex.length() > expectedLength) {
85	                cleanHex = cleanHex.substring(0, expectedLength);
86	            } else {
87	                // 补0到正确长度
88	                while (cleanHex.length() < expectedLength) {
89	                    cleanHex += "0";
90	                }
91	            }
92	        }
93	
94	        // 3. 每两个字符插入一个空格
95	        StringBuilder formatted = new StringBuilder();
96	        for (int i = 0; i < cleanHex.length(); i += 2) {
97	            if (i > 0) {
98	                formatted.append(" ");
99	            }
100	            formatted.append(cleanHex.substring(i, i + 2));
101	        }
102	
103	        return formatted.toString();
104	    }
105	
106	    /**
107	     * 格式化时间差为ASC格式
108	     */
109	    private String formatTimeDelta(Long currentMs, Long startMs) {
110	        if (currentMs == null || startMs == null) {
111	            return "0000.0000";
112	        }
113	
114	        long deltaMs = currentMs - startMs;
115	        double deltaSec = deltaMs / 1000.0;
116	
117	        if (deltaSec < 0) {
118	            deltaSec = 0.0;
119	        }
120	
121	        long wholePart = (long) deltaSec;
122	        long decimalPart = Math.round((deltaSec - wholePart) * 10000);
123	
124	        if (decimalPart >= 10000) {
125	            wholePart += 1;
126	            decimalPart -= 10000;
127	        }
128	
129	        return String.format("%04d.%04d", wholePart, decimalPart);
130	    }
131	
132	    /**
133	     * 格式化帧ID
134	     */
135	    private String formatFrameId(String frameId, Integer idType) {
136	        if (frameId == null || frameId.isEmpty()) {
137	            return "0";
138	        }
139	
140	        String hex = frameId.replaceFirst("^0+(?!$)", "");
141	        if (hex.isEmpty()) {
142	            hex = "0";
143	        }
144	
145	        if (idType != null && idType == 0x02) {
146	            return hex + "x";
147	        }
148	
149	        return hex;
150	    }
151	
152	    /**
153	     * 写入ASC文件头
154	     */
155	    private void writeHeader(BufferedWriter writer, Long startTimeMs) throws IOException {
156	        Date date = new Date(startTimeMs);
157	        SimpleDateFormat sdf = new SimpleDateFormat("EEE MMM dd HH:mm:ss.SSS 'am' yyyy", Locale.ENGLISH);
158	        String dateLine = "date " + sdf.format(date);
159	        writer.write(dateLine);
160	        writer.newLine();
161	
162	        writer.write("base hex timestamps absolute");
163	        writer.newLine();
164	
165	        writer.newLine();
166	    }
167	
168	    /**
169	     * 写入ASC文件
170	     */
171	    private void writeAscFile(List<DecodeC8Result> frameList, String outputPath, Long startTimeMs)
172	            throws IOException {
173	        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputPath))) {
174	            writeHeader(writer, startTimeMs);
175	
176	            for (DecodeC8Result frame : frameList) {
177	                String ascLine = convertFrameToAscLine(frame, startTimeMs);
178	                writer.write(ascLine);
179	                writer.newLine();
180	            }
181	        }
182	    }
183	
184	    /**
185	     * 输入参数校验
186	     */
187	    private void validateInput(List<DecodeC8Result> frameList) {
188	        if (frameList == null || frameList.isEmpty()) {
189	            throw new IllegalArgumentException("CAN报文列表不能为空");
190	        }
191	
192	        if (frameList.get(0).getAcquisitionTime() == null) {
193	            throw new IllegalArgumentException("第一条记录的时间戳不能为空");
194	        }
195	    }
196	
197	    /**
198	     * 创建输出目录
199	     */
200	    private void createOutputDirectory(String outputPath) {
201	        File outputFile = new File(outputPath);
202	        File parentDir = outputFile.getParentFile();
203	        if (parentDir != null && !parentDir.exists()) {
204	            parentDir.mkdirs();
205	        }
206	    }
207	}
