package com.ne.business.dflq.can.utils;

import com.ne.ice.tbox.protocol.dto.DecodeC8Result;

import java.io.*;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.Locale;

/**
 * CAN原始数据转ASC格式文件工具类
 *
 * @author weihong
 * @date 2026-4-13
 */
public class CanToAscConverter {

    /**
     * 将CAN报文列表转换为ASC格式文件
     */
    public void convertToAsc(List<DecodeC8Result> frameList, String outputPath) throws IOException {
        validateInput(frameList);
        Long startTimeMs = frameList.get(0).getAcquisitionTime();
        createOutputDirectory(outputPath);
        writeAscFile(frameList, outputPath, startTimeMs);
    }

    /**
     * 将单个CAN报文转换为ASC格式的一行
     */
    private String convertFrameToAscLine(DecodeC8Result frame, Long startTimeMs) {
        // 1. 时间差（秒），格式化为xxxx.xxxx
        String timeStr = formatTimeDelta(frame.getAcquisitionTime(), startTimeMs);

        // 2. 通道号
        Integer channel = frame.getChannelNumber();

        // 3. 帧ID（根据ID类型添加后缀）
        String idStr = formatFrameId(frame.getDataFrameId(), frame.getDataFrameIdType());

        // 4. 方向（固定为Rx）
        String direction = "Rx";

        // 5. 数据长度（DLC）
        Integer dlc = frame.getDataFieldLength();

        // 6. 格式化数据场 - 关键修复！
        String dataField = formatDataField(frame.getDataFieldHex(), dlc);

        // 7. 拼接为ASC格式
        return String.format("%s %d %s %s d %d %s",
                timeStr,
                channel,
                idStr,
                direction,
                dlc,
                dataField);
    }

    /**
     * 格式化数据场 - 确保每个字节之间有空格分隔
     *
     * @param dataFieldHex 原始数据场字符串（可能连续或已有空格）
     * @param dlc 数据长度
     * @return 格式化后的数据场字符串
     */
    private String formatDataField(String dataFieldHex, Integer dlc) {
        if (dataFieldHex == null || dataFieldHex.isEmpty()) {
            return "";
        }

        // 1. 去除所有现有空格，得到纯净的十六进制字符串
        String cleanHex = dataFieldHex.replaceAll("\\s+", "");

        // 2. 验证长度是否正确（每个字节2个字符）
        int expectedLength = dlc * 2;
        if (cleanHex.length() != expectedLength) {
            // 如果长度不匹配，尝试修复或记录警告
            System.err.println("警告: 数据场长度不匹配，期望: " + expectedLength +
                    "，实际: " + cleanHex.length() + "，数据: " + dataFieldHex);

            // 如果太长，截断；如果太短，补0
            if (cleanHex.length() > expectedLength) {
                cleanHex = cleanHex.substring(0, expectedLength);
            } else {
                // 补0到正确长度
                while (cleanHex.length() < expectedLength) {
                    cleanHex += "0";
                }
            }
        }

        // 3. 每两个字符插入一个空格
        StringBuilder formatted = new StringBuilder();
        for (int i = 0; i < cleanHex.length(); i += 2) {
            if (i > 0) {
                formatted.append(" ");
            }
            formatted.append(cleanHex.substring(i, i + 2));
        }

        return formatted.toString();
    }

    /**
     * 格式化时间差为ASC格式
     */
    private String formatTimeDelta(Long currentMs, Long startMs) {
        if (currentMs == null || startMs == null) {
            return "0000.0000";
        }

        long deltaMs = currentMs - startMs;
        double deltaSec = deltaMs / 1000.0;

        if (deltaSec < 0) {
            deltaSec = 0.0;
        }

        long wholePart = (long) deltaSec;
        long decimalPart = Math.round((deltaSec - wholePart) * 10000);

        if (decimalPart >= 10000) {
            wholePart += 1;
            decimalPart -= 10000;
        }

        return String.format("%04d.%04d", wholePart, decimalPart);
    }

    /**
     * 格式化帧ID
     */
    private String formatFrameId(String frameId, Integer idType) {
        if (frameId == null || frameId.isEmpty()) {
            return "0";
        }

        String hex = frameId.replaceFirst("^0+(?!$)", "");
        if (hex.isEmpty()) {
            hex = "0";
        }

        if (idType != null && idType == 0x02) {
            return hex + "x";
        }

        return hex;
    }

    /**
     * 写入ASC文件头
     */
    private void writeHeader(BufferedWriter writer, Long startTimeMs) throws IOException {
        Date date = new Date(startTimeMs);
        SimpleDateFormat sdf = new SimpleDateFormat("EEE MMM dd HH:mm:ss.SSS 'am' yyyy", Locale.ENGLISH);
        String dateLine = "date " + sdf.format(date);
        writer.write(dateLine);
        writer.newLine();

        writer.write("base hex timestamps absolute");
        writer.newLine();

        writer.newLine();
    }

    /**
     * 写入ASC文件
     */
    private void writeAscFile(List<DecodeC8Result> frameList, String outputPath, Long startTimeMs)
            throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputPath))) {
            writeHeader(writer, startTimeMs);

            for (DecodeC8Result frame : frameList) {
                String ascLine = convertFrameToAscLine(frame, startTimeMs);
                writer.write(ascLine);
                writer.newLine();
            }
        }
    }

    /**
     * 输入参数校验
     */
    private void validateInput(List<DecodeC8Result> frameList) {
        if (frameList == null || frameList.isEmpty()) {
            throw new IllegalArgumentException("CAN报文列表不能为空");
        }

        if (frameList.get(0).getAcquisitionTime() == null) {
            throw new IllegalArgumentException("第一条记录的时间戳不能为空");
        }
    }

    /**
     * 创建输出目录
     */
    private void createOutputDirectory(String outputPath) {
        File outputFile = new File(outputPath);
        File parentDir = outputFile.getParentFile();
        if (parentDir != null && !parentDir.exists()) {
            parentDir.mkdirs();
        }
    }
}

