package com.ne.business.dflq.can.utils;

import com.ne.business.dflq.can.config.CosConfig;
import com.qcloud.cos.COSClient;
import com.qcloud.cos.ClientConfig;
import com.qcloud.cos.auth.BasicCOSCredentials;
import com.qcloud.cos.auth.COSCredentials;
import com.qcloud.cos.http.HttpProtocol;
import com.qcloud.cos.model.GetObjectRequest;
import com.qcloud.cos.model.ObjectMetadata;
import com.qcloud.cos.model.PutObjectRequest;
import com.qcloud.cos.region.Region;
import com.qcloud.cos.utils.IOUtils;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import javax.annotation.PostConstruct;
import java.io.*;
import java.net.URI;

/**
 * COS文件下载工具类
 * 支持从COS URL或签名URL下载文件
 * 凭证和区域从配置文件加载
 *
 * @author weihong
 * @date 2026-06-08
 */
@Slf4j
@Component
public class CosFileDownloader {

    private static String SECRET_ID;
    private static String SECRET_KEY;
    private static String REGION_NAME;

    private static volatile COSClient COS_CLIENT_INSTANCE = null;

    @Autowired
    private CosConfig cosConfig;

    @PostConstruct
    public void init() {
        SECRET_ID = cosConfig.getSecretId();
        SECRET_KEY = cosConfig.getSecretKey();
        REGION_NAME = cosConfig.getRegion();
        log.info("COS配置加载完成: region={}", REGION_NAME);
    }

    /**
     * 获取COS客户端单例
     */
    private static COSClient getCosClientInstance() {
        if (COS_CLIENT_INSTANCE == null) {
            synchronized (CosFileDownloader.class) {
                if (COS_CLIENT_INSTANCE == null) {
                    COSCredentials cosCredentials = new BasicCOSCredentials(SECRET_ID, SECRET_KEY);
                    ClientConfig cosClientConfig = new ClientConfig(new Region(REGION_NAME));
                    cosClientConfig.setHttpProtocol(HttpProtocol.http);
                    COS_CLIENT_INSTANCE = new COSClient(cosCredentials, cosClientConfig);
                }
            }
        }
        return COS_CLIENT_INSTANCE;
    }

    /**
     * 从COS URL下载文件
     * 支持完整URL格式：http://{bucket}.cos.{region}.myqcloud.com/{key}
     * 或签名URL格式：http://{bucket}.cos.{region}.myqcloud.com/{key}?q-sign-...
     *
     * @param fileUrl COS文件URL
     * @return 文件字节数据
     */
    public static byte[] downloadFromCosUrl(String fileUrl) {
        log.info("开始从COS下载文件: {}", fileUrl);

        try {
            URI uri = new URI(fileUrl);
            String host = uri.getHost();
            String path = uri.getPath();

            // 从host中提取bucket名称：{bucket}.cos.{region}.myqcloud.com
            String bucketName = extractBucketName(host);
            // 去掉路径开头的 /
            String cosKey = path.startsWith("/") ? path.substring(1) : path;

            log.info("解析COS地址: bucket={}, key={}", bucketName, cosKey);

            return downloadFromCos(bucketName, cosKey);
        } catch (Exception e) {
            log.error("从COS URL下载文件失败: {}", fileUrl, e);
            throw new RuntimeException("从COS下载文件失败: " + fileUrl, e);
        }
    }

    /**
     * 从COS下载文件（使用bucket名称和key）
     *
     * @param bucketName COS bucket名称
     * @param cosKey     COS文件key
     * @return 文件字节数据
     */
    public static byte[] downloadFromCos(String bucketName, String cosKey) {
        log.info("从COS下载文件: bucket={}, key={}", bucketName, cosKey);

        COSClient cosClient = getCosClientInstance();
        GetObjectRequest getObjectRequest = new GetObjectRequest(bucketName, cosKey);

        try (InputStream cosObjectInput = cosClient.getObject(getObjectRequest).getObjectContent()) {
            byte[] data = IOUtils.toByteArray(cosObjectInput);
            log.info("从COS下载文件成功: bucket={}, key={}, 大小={} 字节", bucketName, cosKey, data.length);
            return data;
        } catch (Exception e) {
            log.error("从COS下载文件失败: bucket={}, key={}, 错误: {}", bucketName, cosKey, e.getMessage(), e);
            throw new RuntimeException("从COS下载文件失败", e);
        }
    }

    /**
     * 删除COS文件（使用bucket名称和key）
     *
     * @param bucketName COS bucket名称
     * @param cosKey     COS文件key
     */
    public static void deleteFile(String bucketName, String cosKey) {
        log.info("开始删除COS文件: bucket={}, key={}", bucketName, cosKey);

        COSClient cosClient = getCosClientInstance();
        try {
            cosClient.deleteObject(bucketName, cosKey);
            log.info("删除COS文件成功: bucket={}, key={}", bucketName, cosKey);
        } catch (Exception e) {
            log.error("删除COS文件失败: bucket={}, key={}, 错误: {}", bucketName, cosKey, e.getMessage(), e);
            throw new RuntimeException("删除COS文件失败", e);
        }
    }

    /**
     * 从COS host中提取bucket名称
     * 格式：{bucket}.cos.{region}.myqcloud.com
     *
     * @param host 主机名
     * @return bucket名称
     */
    private static String extractBucketName(String host) {
        if (host == null || host.isEmpty()) {
            throw new IllegalArgumentException("COS URL host不能为空");
        }
        // 格式：{bucket}.cos.{region}.myqcloud.com
        String[] parts = host.split("\\.");
        if (parts.length < 4) {
            throw new IllegalArgumentException("无法从host解析bucket名称: " + host);
        }
        return parts[0];
    }

    /**
     * 上传字节数组到COS
     *
     * @param bucketName COS bucket名称
     * @param cosKey     COS文件key
     * @param data       文件字节数据
     */
    public static void putFile(String bucketName, String cosKey, byte[] data) {
        log.info("开始上传文件到COS: bucket={}, key={}, 大小={} 字节", bucketName, cosKey, data.length);

        COSClient cosClient = getCosClientInstance();
        try (InputStream inputStream = new ByteArrayInputStream(data)) {
            ObjectMetadata objectMetadata = new ObjectMetadata();
            objectMetadata.setContentLength(data.length);
            PutObjectRequest putObjectRequest = new PutObjectRequest(bucketName, cosKey, inputStream, objectMetadata);
            cosClient.putObject(putObjectRequest);
            log.info("上传文件到COS成功: bucket={}, key={}", bucketName, cosKey);
        } catch (Exception e) {
            log.error("上传文件到COS失败: bucket={}, key={}, 错误: {}", bucketName, cosKey, e.getMessage(), e);
            throw new RuntimeException("上传文件到COS失败", e);
        }
    }

    /**
     * 上传本地文件到COS
     *
     * @param bucketName COS bucket名称
     * @param cosKey     COS文件key
     * @param file       本地文件
     */
    public static void putFile(String bucketName, String cosKey, File file) {
        log.info("开始上传本地文件到COS: bucket={}, key={}, 文件路径={}", bucketName, cosKey, file.getAbsolutePath());

        COSClient cosClient = getCosClientInstance();
        PutObjectRequest putObjectRequest = new PutObjectRequest(bucketName, cosKey, file);
        try {
            cosClient.putObject(putObjectRequest);
            log.info("上传本地文件到COS成功: bucket={}, key={}", bucketName, cosKey);
        } catch (Exception e) {
            log.error("上传本地文件到COS失败: bucket={}, key={}, 错误: {}", bucketName, cosKey, e.getMessage(), e);
            throw new RuntimeException("上传本地文件到COS失败", e);
        }
    }

    /**
     * 从COS URL中解析bucket名称和key，并上传文件
     *
     * @param targetUrl 目标COS URL（用于解析bucket和key）
     * @param data      文件字节数据
     */
    public static void putFileByUrl(String targetUrl, byte[] data) {
        log.info("开始上传文件到COS URL: {}", targetUrl);

        try {
            URI uri = new URI(targetUrl);
            String host = uri.getHost();
            String path = uri.getPath();

            // 从host中提取bucket名称
            String bucketName = extractBucketName(host);
            // 去掉路径开头的 /
            String cosKey = path.startsWith("/") ? path.substring(1) : path;

            log.info("解析COS上传地址: bucket={}, key={}", bucketName, cosKey);

            putFile(bucketName, cosKey, data);
        } catch (Exception e) {
            log.error("上传文件到COS URL失败: {}", targetUrl, e);
            throw new RuntimeException("上传文件到COS URL失败: " + targetUrl, e);
        }
    }

    /**
     * 从COS URL中解析bucket名称和key，并上传本地文件
     *
     * @param targetUrl 目标COS URL（用于解析bucket和key）
     * @param file      本地文件
     */
    public static void putFileByUrl(String targetUrl, File file) {
        log.info("开始上传本地文件到COS URL: {}", targetUrl);

        try {
            URI uri = new URI(targetUrl);
            String host = uri.getHost();
            String path = uri.getPath();

            // 从host中提取bucket名称
            String bucketName = extractBucketName(host);
            // 去掉路径开头的 /
            String cosKey = path.startsWith("/") ? path.substring(1) : path;

            log.info("解析COS上传地址: bucket={}, key={}", bucketName, cosKey);

            putFile(bucketName, cosKey, file);
        } catch (Exception e) {
            log.error("上传本地文件到COS URL失败: {}", targetUrl, e);
            throw new RuntimeException("上传本地文件到COS URL失败: " + targetUrl, e);
        }
    }
