package com.ne.business.dflq.can.utils;

import com.ne.boot.common.entity.Page;
import io.swagger.annotations.ApiModelProperty;
import lombok.Data;

import java.io.Serializable;
import java.util.List;

/**
 * 通用分页结果类
 * @param <T> 实体数据类型
 */
@Data
public class PageResult<T> implements Serializable {

    private static final long serialVersionUID = 1L;

    @ApiModelProperty(value = "总记录数")
    private Long total;

    @ApiModelProperty(value = "当前页码")
    private Long pageIndex;

    @ApiModelProperty(value = "当前页大小")
    private Long pageSize;

    @ApiModelProperty(value = "总页数")
    private Long totalPages;

    @ApiModelProperty(value = "当前页数据")
    private List<T> pageData;

    @ApiModelProperty(value = "是否为全量查询")
    private Boolean fetchAll;

    /**
     * 空构造函数
     */
    public PageResult() {
    }

    /**
     * 全参数构造函数
     */
    public PageResult(Long total, Long pageIndex, Long pageSize, List<T> pageData) {
        this.total = total;
        this.pageIndex = pageIndex;
        this.pageSize = pageSize;
        this.pageData = pageData;
        if (total != null && pageSize != null && pageSize > 0) {
            this.totalPages = (total + pageSize - 1) / pageSize;
        } else {
            this.totalPages = 0L;
        }
    }

    /**
     * 从Page对象构建
     */
    public static <T> PageResult<T> from(Page page, List<T> data) {
        return new PageResult<>(
                page.getTotalCount(),
                page.getPageIndex(),
                page.getPageSize(),
                data
        );
    }
}

