package com.ne.business.dflq.can.utils;

import com.github.luben.zstd.ZstdInputStream;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;

/**
 * zstd工具类
 * @author lyl
 * @date 2026/3/9
 */
public class ZstdUtils {
    /**
     * 使用Zstandard解压
     */
    public static byte[] decompressZstd(byte[] compressedData) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(compressedData);
             ZstdInputStream zstdIn = new ZstdInputStream(bais);
             ByteArrayOutputStream baos = new ByteArrayOutputStream()) {

            byte[] buffer = new byte[8192];
            int len;
            while ((len = zstdIn.read(buffer)) > 0) {
                baos.write(buffer, 0, len);
            }
            return baos.toByteArray();
        } catch (Exception e) {
            throw new RuntimeException("文件解压失败", e);
        }
    }
}

